package com.quincaisoft.finance.application;import com.quincaisoft.finance.api.*;import com.quincaisoft.finance.infrastructure.*;import com.quincaisoft.shared.*;import jakarta.persistence.*;import org.springframework.stereotype.Service;import tools.jackson.databind.json.JsonMapper;import java.util.*;
@Service public class DefaultManualJournalService implements ManualJournalService{
 private final EntityManager em;private final ScopedTransactions tx;private final FinanceService finance;private final FinanceOperations ops;public DefaultManualJournalService(EntityManager em,ScopedTransactions tx,FinanceService finance,JsonMapper json){this.em=em;this.tx=tx;this.finance=finance;ops=new FinanceOperations(em,json);}
 private void reason(String s){if(s==null||s.trim().length()<3||s.length()>2000)throw new IllegalArgumentException("Reason required");}
 private long amount(String s){if(s==null||!s.matches("0|[1-9][0-9]*"))throw new IllegalArgumentException("Exact nonnegative whole XAF required");return Long.parseLong(s);}
 private List<FinanceService.Entry> entries(List<Line> lines){if(lines==null||lines.size()>200)throw new IllegalArgumentException("2–200 balanced lines required");var result=lines.stream().map(l->new FinanceService.Entry(l.account(),amount(l.debitXaf()),amount(l.creditXaf()))).toList();FinanceService.balanced(result);return result;}
 private ManualJournal row(UUID id){var s=TenantContext.current();var r=em.find(ManualJournal.class,new ManualJournal.Key(s.tenantId(),s.companyId(),id),LockModeType.PESSIMISTIC_WRITE);if(r==null)throw new NoSuchElementException("Scoped manual journal not found");return r;}
 private List<Line> lines(UUID id){return em.createQuery("select l from ManualJournalLine l where l.manualId=:id order by l.id",ManualJournalLine.class).setParameter("id",id).getResultList().stream().map(l->new Line(l.account,""+l.debitXaf,""+l.creditXaf)).toList();}
 private Journal view(ManualJournal r){return new Journal(r.id,r.businessDate,r.status,r.reason,r.createdBy,r.approvedBy,r.reversalOf,r.journalId,r.version,lines(r.id));}
 public Journal get(UUID id){return tx.execute(()->view(row(id)));}
 public List<Journal> list(){return tx.execute(()->em.createQuery("select r from ManualJournal r order by r.businessDate desc,r.id",ManualJournal.class).setMaxResults(200).getResultList().stream().map(this::view).toList());}
 private Journal create(Draft p,UUID original){finance.requireOpenPeriod(p.businessDate());var items=entries(p.lines());var s=TenantContext.current();var r=new ManualJournal();r.tenantId=s.tenantId();r.companyId=s.companyId();r.branchId=s.branchId();r.id=UUID.randomUUID();r.businessDate=p.businessDate();r.status="DRAFT";r.reason=p.reason();r.createdBy=s.actorId();r.reversalOf=original;em.persist(r);for(var item:items){var l=new ManualJournalLine();l.tenantId=s.tenantId();l.companyId=s.companyId();l.branchId=s.branchId();l.id=UUID.randomUUID();l.manualId=r.id;l.account=item.account();l.debitXaf=item.debit();l.creditXaf=item.credit();em.persist(l);}em.flush();return view(r);}
 public Journal draft(Draft p){reason(p.reason());entries(p.lines());return tx.execute(()->ops.once(p.operationId(),"MANUAL_DRAFT|"+p,"ManualJournalDrafted",Journal.class,()->create(p,null),Journal::id));}
 public Journal command(UUID id,String action,Command p){reason(p.reason());return tx.execute(()->ops.once(p.operationId(),"MANUAL_COMMAND|"+id+"|"+action+"|"+p,"ManualJournalChanged",Journal.class,()->{var r=row(id);finance.requireOpenPeriod(r.businessDate);if(r.version!=p.version())throw new RevisionConflict("Journal changed");var actor=TenantContext.current().actorId();switch(action){case "submit"->{if(!Set.of("DRAFT","REJECTED").contains(r.status))throw new IllegalStateException("Editable journal required");r.status="IN_REVIEW";r.submittedBy=actor;}case "approve","reject"->{if(!r.status.equals("IN_REVIEW"))throw new IllegalStateException("Submitted journal required");if(actor.equals(r.submittedBy)||actor.equals(r.createdBy))throw new IllegalArgumentException("Independent journal approver required");if(action.equals("approve")){r.journalId=finance.post(r.id,p.operationId(),r.businessDate,r.reversalOf==null?"MANUAL_JOURNAL":"MANUAL_REVERSAL",entries(lines(r.id)));r.approvedBy=actor;r.status="POSTED";}else r.status="REJECTED";}default->throw new IllegalArgumentException("Unsupported journal command");}r.reason=p.reason();em.flush();return view(r);},Journal::id));}
 public Journal reversal(UUID id,Reversal p){reason(p.reason());return tx.execute(()->ops.once(p.operationId(),"MANUAL_REVERSE|"+id+"|"+p,"ManualReversalDrafted",Journal.class,()->{var r=row(id);if(r.version!=p.version())throw new RevisionConflict("Journal changed");if(!r.status.equals("POSTED")||r.reversalOf!=null)throw new IllegalStateException("Posted original manual journal required; reverse system entries through their source workflow");var reverse=lines(id).stream().map(l->new Line(l.account(),l.creditXaf(),l.debitXaf())).toList();return create(new Draft(p.operationId(),p.businessDate(),p.reason(),reverse),id);},Journal::id));}
}